mapper.select:
SELECT d.id as dialog_id, d.user_id, d.status, d.created_time, d.updated_time, d.title, m.id as last_message_id, m.content as last_message_content, m.send_time as last_message_send_time, (SELECT COUNT(*) FROM assistant_message WHERE dialog_id = d.id) as message_count FROM assistant_dialog d LEFT JOIN assistant_message m ON m.id = ( SELECT id FROM assistant_message WHERE dialog_id = d.id ORDER BY send_time DESC LIMIT 1 )
AND d.user_id = #{query.userId}
AND d.status = #{query.status}
AND d.created_time >= #{query.startTime}
AND d.created_time <= #{query.endTime}
ORDER BY d.updated_time DESC
